class NegativeAmountError(ValueError):
    pass

def deposit(amount):
    if amount < 0:
        raise NegativeAmountError(f"Cannot deposit a negative amount: {amount}")
    return amount

try:
    deposit(-10)
except ValueError as e:
    print(f"Rejected: {e}")
except NegativeAmountError as e:
    print(f"Specifically negative: {e}")

